// AUTO-GENERATED BY silc — DO NOT EDIT
/** Capsule vs AABB/plane collision + gravity for FPS movement. */

import type { ColliderPart } from "../adapters/kitBuilder.ts";
import type { GameSystem } from "../kernel/systems.ts";
import type { World } from "../kernel/world.ts";

/** `hull.aabb` holds full dimensions, matching the baked kit piece sizes. */
export type ColliderComp = {
  shape: string;
  size: number;
  hull?: { aabb?: { x: number; y: number; z: number } } | null;
  parts?: ColliderPart[] | null;
  static?: boolean;
};

type Solid = {
  minX: number;
  maxX: number;
  minY: number;
  maxY: number;
  minZ: number;
  maxZ: number;
  ground: boolean;
};

/** Half-extents of a collider that carries no explicit part list. */
function defaultPart(c: ColliderComp): ColliderPart {
  const hx = (c.hull?.aabb?.x ?? c.size) * 0.5;
  const hy = (c.hull?.aabb?.y ?? c.size) * 0.5;
  const hz = (c.hull?.aabb?.z ?? c.size) * 0.5;
  return { cx: 0, cy: hy, cz: 0, hx, hy, hz };
}

export function createPhysicsSystem(world: World): GameSystem {
  return {
    name: "physics",
    order: 15,
    fixedUpdate(ctx) {
      const solids: Solid[] = [];

      for (const [id, raw] of world.query("collider")) {
        const c = raw as ColliderComp;
        const p = world.worldPosition(id);
        if (c.shape === "plane") {
          solids.push({
            minX: p.x - c.size * 0.5,
            maxX: p.x + c.size * 0.5,
            minY: p.y - 0.05,
            maxY: p.y + 0.05,
            minZ: p.z - c.size * 0.5,
            maxZ: p.z + c.size * 0.5,
            ground: true,
          });
          continue;
        }
        // Dynamic capsules (player/npc) are resolved later — skip as solids.
        if (
          (c.shape === "capsule" || c.shape === "box") &&
          (world.hasComponent("movement", id) || world.hasComponent("pawn", id) || world.hasComponent("npc", id))
        ) {
          continue;
        }
        // Rotate each local box by the entity yaw and bound the result.
        const yaw = world.transform(id)?.yaw ?? 0;
        const cos = Math.cos(yaw);
        const sin = Math.sin(yaw);
        for (const part of c.parts?.length ? c.parts : [defaultPart(c)]) {
          const cx = part.cx * cos + part.cz * sin;
          const cz = -part.cx * sin + part.cz * cos;
          const hx = Math.abs(part.hx * cos) + Math.abs(part.hz * sin);
          const hz = Math.abs(part.hx * sin) + Math.abs(part.hz * cos);
          solids.push({
            minX: p.x + cx - hx,
            maxX: p.x + cx + hx,
            minY: p.y + part.cy - part.hy,
            maxY: p.y + part.cy + part.hy,
            minZ: p.z + cz - hz,
            maxZ: p.z + cz + hz,
            ground: false,
          });
        }
      }

      for (const [id, raw] of world.query("collider")) {
        const c = raw as ColliderComp;
        if (c.shape !== "capsule" && c.shape !== "box") continue;
        if (
          !world.hasComponent("movement", id) &&
          !world.hasComponent("pawn", id) &&
          !world.hasComponent("npc", id)
        ) {
          continue;
        }
        const vel = world.getComponent<{ vx: number; vy: number; vz: number }>("velocity", id) ?? {
          vx: 0,
          vy: 0,
          vz: 0,
        };
        const radius = (c.hull?.aabb?.x ?? c.size * 0.7) * 0.5;
        const halfH = (c.hull?.aabb?.y ?? c.size) * 0.5;
        let t = world.transform(id)!;
        let x = t.x + vel.vx * ctx.fixedDt;
        let y = t.y + vel.vy * ctx.fixedDt;
        let z = t.z + vel.vz * ctx.fixedDt;
        vel.vy -= 18 * ctx.fixedDt;
        if (vel.vy < -30) vel.vy = -30;

        // Resolve support first, taking the highest surface underfoot. Doing
        // this per-solid would let a low prop snap the capsule below the floor
        // it is standing on, which then reads as being stuck inside the floor.
        let groundY = -Infinity;
        for (const s of solids) {
          if (s.ground) {
            const onPad = x >= s.minX && x <= s.maxX && z >= s.minZ && z <= s.maxZ;
            if (onPad && y < s.maxY) groundY = Math.max(groundY, s.maxY);
            continue;
          }
          const supports =
            x > s.minX - radius &&
            x < s.maxX + radius &&
            z > s.minZ - radius &&
            z < s.maxZ + radius &&
            y <= s.maxY + 0.08 &&
            y >= s.maxY - 0.35 &&
            vel.vy <= 0;
          if (supports) groundY = Math.max(groundY, s.maxY);
        }
        let grounded = false;
        if (groundY > -Infinity) {
          y = groundY;
          if (vel.vy < 0) vel.vy = 0;
          grounded = true;
        }

        for (const s of solids) {
          if (s.ground) continue;
          // AABB vs capsule (treated as vertical capsule → horizontal circle + height)
          const closestX = Math.max(s.minX, Math.min(x, s.maxX));
          const closestZ = Math.max(s.minZ, Math.min(z, s.maxZ));
          const dx = x - closestX;
          const dz = z - closestZ;
          const distSq = dx * dx + dz * dz;
          const feet = y;
          const head = y + halfH * 2;
          const overlapsY = head > s.minY && feet < s.maxY;
          if (overlapsY && distSq < radius * radius && distSq > 1e-8) {
            const dist = Math.sqrt(distSq);
            const push = (radius - dist) / dist;
            x += dx * push;
            z += dz * push;
          } else if (overlapsY && distSq <= 1e-8) {
            // Center inside solid — push out on smallest axis.
            const left = Math.abs(x - s.minX);
            const right = Math.abs(s.maxX - x);
            const near = Math.abs(z - s.minZ);
            const far = Math.abs(s.maxZ - z);
            const m = Math.min(left, right, near, far);
            if (m === left) x = s.minX - radius;
            else if (m === right) x = s.maxX + radius;
            else if (m === near) z = s.minZ - radius;
            else z = s.maxZ + radius;
          }
        }

        world.setTransform(id, { x, y, z });
        world.addComponent("velocity", id, vel);
        world.addComponent("grounded", id, { value: grounded });
      }
    },
  };
}
